    pathData: String,
): ImageVector = ImageVector
    .Builder(name, 24.dp, 24.dp, 960f, 960f)
    .addGroup(translationY = 960f)
    .addPath(addPathNodes(pathData), fill = SolidColor(Color.Black))
    .clearGroup()
    .build()

